-- Employee shipped/unshipped orders | mysql
-- Generated by scripts/export-demo-sql.ts; display formatting only.
-- Ordered sample parameters: [1,0,1,0]
-- r2 project: merged; Compatible row-level input block
-- r1 aggregate: merged; Compatible row-level input block
-- r0 sort: merged; Track output ordering without a new query block
select
  `r3`.`employee_id` as `employee_id`,
  cast(
    sum(
      cast(
        case
          when (
            (`r6`.`order_id` is not null)
            and (`r6`.`shipped_date` is not null)
          ) then cast(? as double)
          else cast(? as double)
        end as double
      )
    ) as double
  ) as `shipped`,
  cast(
    sum(
      cast(
        case
          when (
            (`r6`.`order_id` is not null)
            and (`r6`.`shipped_date` is null)
          ) then cast(? as double)
          else cast(? as double)
        end as double
      )
    ) as double
  ) as `unshipped`
from
  `employees` as `r3`
  left join `orders` as `r6` on (`r3`.`employee_id` = `r6`.`employee_id`)
group by
  `r3`.`employee_id`
order by
  `r3`.`employee_id` asc;
